package com.bsit.p2p_chat
import android.content.Context import androidx.room.Room import com.bsit.p2p_chat.data.datasource.ChatLocalDataSource import com.bsit.p2p_chat.data.datasource.PeerDiscoveryDataSource import com.bsit.p2p_chat.data.local.AppDatabase import com.bsit.p2p_chat.data.repository.ChatRepository import com.bsit.p2p_chat.data.repository.ChatRepositoryImpl import com.bsit.p2p_chat.socket.InMemoryMessageTransport import com.bsit.p2p_chat.socket.MessageTransport import com.bsit.p2p_chat.socket.SocketMessageTransport import com.bsit.p2p_chat.wifi_direct.WifiDirectManager import com.bsit.p2p_chat.wifi_direct.WifiDirectPeerDiscoveryDataSource import kotlinx.coroutines.CoroutineScope import kotlinx.coroutines.Dispatchers import kotlinx.coroutines.SupervisorJob import kotlinx.coroutines.cancel
class AppContainer( context: Context , val wifiDirectManager: WifiDirectManager ) {
private val appScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
private val database: AppDatabase = Room.databaseBuilder( context.applicationContext, AppDatabase::class.java, "p2p_chat.db" ).build()
private val localDataSource = ChatLocalDataSource(database.chatMessageDao()) val socketMessageTransport = SocketMessageTransport(appScope) val messageTransport: MessageTransport = InMemoryMessageTransport() val peerDiscoveryDataSource: PeerDiscoveryDataSource = WifiDirectPeerDiscoveryDataSource(wifiDirectManager)
val chatRepository: ChatRepository = ChatRepositoryImpl( local = localDataSource, transport = messageTransport, scope = appScope )
fun clear() { appScope.cancel() } }

package com.bsit.p2p_chat
import android.content.Context import android.net.wifi.p2p.WifiP2pManager import android.os.Looper import androidx.room.Room import com.bsit.p2p_chat.data.datasource.ChatLocalDataSource import com.bsit.p2p_chat.data.datasource.PeerDiscoveryDataSource import com.bsit.p2p_chat.data.local.AppDatabase import com.bsit.p2p_chat.data.repository.ChatRepository import com.bsit.p2p_chat.data.repository.ChatRepositoryImpl import com.bsit.p2p_chat.socket.InMemoryMessageTransport import com.bsit.p2p_chat.socket.MessageTransport import com.bsit.p2p_chat.socket.SocketMessageTransport import com.bsit.p2p_chat.wifi_direct.WifiDirectManager import com.bsit.p2p_chat.wifi_direct.WifiDirectPeerDiscoveryDataSource import kotlinx.coroutines.CoroutineScope import kotlinx.coroutines.Dispatchers import kotlinx.coroutines.SupervisorJob import kotlinx.coroutines.cancel
class AppContainer( context: Context ) {
private val appScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
private val wifiP2pManager = context.getSystemService(Context.WIFI_P2P_SERVICE) as WifiP2pManager private val channel = wifiP2pManager.initialize(context, Looper.getMainLooper(), null)
val socketMessageTransport = SocketMessageTransport(appScope) val wifiDirectManager = WifiDirectManager( context = context, manager = wifiP2pManager, channel = channel, socketTransport = socketMessageTransport )
private val database: AppDatabase = Room.databaseBuilder( context.applicationContext, AppDatabase::class.java, "p2p_chat.db" ).build()
private val localDataSource = ChatLocalDataSource(database.chatMessageDao()) val messageTransport: MessageTransport = InMemoryMessageTransport() val peerDiscoveryDataSource: PeerDiscoveryDataSource = WifiDirectPeerDiscoveryDataSource(wifiDirectManager)
val chatRepository: ChatRepository = ChatRepositoryImpl( local = localDataSource, transport = messageTransport, scope = appScope )
fun clear() { appScope.cancel() } }

package com.bsit.p2p_chat.data.repository

import com.bsit.p2p_chat.data.datasource.ChatLocalDataSource
import com.bsit.p2p_chat.data.local.entity.ChatMessageEntity
import com.bsit.p2p_chat.data.model.ChatMessageModel
import com.bsit.p2p_chat.data.model.SenderType
import com.bsit.p2p_chat.socket.MessageTransport
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch

class ChatRepositoryImpl(
    private val local: ChatLocalDataSource,
    private val transport: MessageTransport,
    scope: CoroutineScope
) : ChatRepository {

    init {
        scope.launch {
            transport.incomingMessages().collect { (peerAddress, text) ->
                local.insert(
                    ChatMessageEntity(
                        text = text,
                        senderType = SenderType.RECEIVED.name,
                        timestamp = System.currentTimeMillis(),
                        peerAddress = peerAddress
                    )
                )
            }
        }
    }

    override fun observeMessages(peerAddress: String): Flow<List<ChatMessageModel>> {
        return local.observeMessages(peerAddress).map { list ->
            list.map { entity ->
                ChatMessageModel(
                    id = entity.id,
                    text = entity.text,
                    senderType = SenderType.entries.firstOrNull { it.name == entity.senderType }
                        ?: SenderType.RECEIVED,
                    timestamp = entity.timestamp,
                    peerAddress = entity.peerAddress
                )
            }
        }
    }

    override suspend fun sendMessage(peerAddress: String, text: String): Result<Unit> {
        val sendResult = transport.send(peerAddress, text)
        val senderType = if (sendResult.isSuccess) SenderType.SENT else SenderType.FAILED

        local.insert(
            ChatMessageEntity(
                text = text,
                senderType = senderType.name,
                timestamp = System.currentTimeMillis(),
                peerAddress = peerAddress
            )
        )

        return sendResult
    }
}

