package com.bsit.p2p_chat.ui.discovery

import android.net.wifi.p2p.WifiP2pDevice
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.bsit.p2p_chat.data.datasource.PeerDiscoveryDataSource
import com.bsit.p2p_chat.wifi_direct.WifiDirectManager
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import com.bsit.p2p_chat.socket.SocketMessageTransport
import com.bsit.p2p_chat.socket.ConnectionStatus

class DiscoveryViewModel(
    private val peerDataSource: PeerDiscoveryDataSource ,
    private val wifiDirectManager: WifiDirectManager,
    private val socketTransport: SocketMessageTransport
) : ViewModel() {

    private val _uiState = MutableStateFlow(DiscoveryUiState())
    val uiState: StateFlow<DiscoveryUiState> = _uiState.asStateFlow()

    private val _navigateToChat = MutableSharedFlow<String>()
    val navigateToChat = _navigateToChat.asSharedFlow()

    init { // Khởi chạy coroutine ngay khi ViewModel được tạo
        observePeers()
        observeWifiState()
        observeConnection()
        observeSocketConnection()
    }

    private fun observePeers() {
        peerDataSource.getPeers()
            .catch { e ->
                _uiState.update { it.copy(errorMessage = e.message) }
            }
            .onEach { peers ->
                _uiState.update { it.copy( peers = peers)  }
            }.launchIn(viewModelScope)
    }

    private fun observeWifiState() {
        viewModelScope.launch {
            peerDataSource.observeWifiState()
                .catch { e ->
                    _uiState.update { it.copy(errorMessage = e.message) }
                }
                .collect { isEnabled ->
                _uiState.update { it.copy(isWifiEnabled = isEnabled) }
            }
        }
    }

    private fun observeConnection() {
        wifiDirectManager.connectionInfo.
        onEach { info ->
            if (info?.groupFormed == true) {
                // Nếu kết nối thành công và nhóm đã được tạo
                // Lấy địa chỉ của chủ sở hữu nhóm để bắt đầu chat
                val groupOwnerAddress = info.groupOwnerAddress?.hostAddress
                if (groupOwnerAddress != null) {
                    _uiState.update { it.copy(isConnecting = false) } // Dừng trạng thái loading
                    _navigateToChat.emit(groupOwnerAddress) // Gửi sự kiện điều hướng
                }
            }
        }.launchIn(viewModelScope)
    }

    fun discoverPeers() {
        viewModelScope.launch {
            if (!_uiState.value.isWifiEnabled) {
                _uiState.update { it.copy(errorMessage = "Wifi is off. Turn it on first.") }
                return@launch
            }
            _uiState.update { it.copy(isDiscovering = true, errorMessage = null) }
            runCatching { peerDataSource.discoverPeers() }
                .onFailure { e ->
                    _uiState.update { it.copy(isDiscovering = false, errorMessage = e.message) }
                }
        }
    }

    fun connectToPeer(peerDeviceAddress: String) {
        viewModelScope.launch {
            val peerDevice = peerDataSource.getPeers().first().firstOrNull() {
                it.deviceAddress == peerDeviceAddress
            }
            if ( peerDevice != null) {
                runCatching {
                    peerDataSource.connectToPeer(peerDevice)
                }.onFailure { e ->
                    _uiState.update { it.copy(errorMessage = "Connection failed: ${e.message}")
                    }
                }
            }
            else {
                _uiState.update { it.copy(errorMessage = "Device not found.") }
            }
        }
    }

    private fun observeSocketConnection() {
        socketTransport.connectionState
            .onEach { status ->
                _uiState.update { it.copy(isConnecting = (status == ConnectionStatus.CONNECTING)) }
                if (status == ConnectionStatus.CONNECTED) {
                    // Khi kết nối thành công, điều hướng đến màn hình chat
                    // Chúng ta cần một địa chỉ để định danh cuộc trò chuyện, có thể dùng IP của server
                    // Hoặc một ID giả "manual_test_chat"
                    _navigateToChat.emit("manual_test_chat")
                }
            }
            .launchIn(viewModelScope)
    }

    fun startManualServer() {
        socketTransport.startServer()
    }

    fun connectToManualServer(ipAddress: String) {
        if (ipAddress.isNotBlank()) {
            socketTransport.connectToServer(ipAddress)
        } else {
            _uiState.update { it.copy(errorMessage = "Please enter a valid IP address.") }
        }
    }

    fun startDiscovery() {
        viewModelScope.launch {
            _uiState.update { it.copy(isDiscovering = true) }
            peerDataSource.discoverPeers()
        }
    }

    fun stopDiscovery() {
        viewModelScope.launch {
            peerDataSource.stopDiscoverPeers()
            _uiState.update { it.copy(isDiscovering = false) }
        }
    }

    fun onWifiToggleClicked(enabled: Boolean) {
        if (enabled) {
            viewModelScope.launch {
                peerDataSource.requestToEnableWifi()
            }
        }
    }

    // Hàm được gọi từ UI khi người dùng nhấn vào một thiết bị
    fun connectToDevice(device: WifiP2pDevice) {
        viewModelScope.launch {
            // Cập nhật UI để hiển thị trạng thái đang kết nối
            _uiState.update { it.copy(isConnecting = true, connectingDeviceName = device.deviceName) }
            peerDataSource.connectToPeer(device)
        }
    }
}

