package com.bsit.p2p_chat

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.runtime.Composable
import androidx.compose.runtime.DisposableEffect
import androidx.compose.ui.platform.LocalLifecycleOwner
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleEventObserver
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.bsit.p2p_chat.ui.chat.ChatRoute
import com.bsit.p2p_chat.ui.discovery.DiscoveryRoute
import com.bsit.p2p_chat.ui.theme.P2P_ChatTheme
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    // XÓA BỎ HOÀN TOÀN CÁC THUỘC TÍNH INJECT
    // @Inject lateinit var wifiDirectManager: WifiDirectManager
    // @Inject lateinit var socketTransport: SocketMessageTransport

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            P2P_ChatTheme {
                // Toàn bộ logic được chuyển vào AppNavigation
                AppNavigation()
            }
        }
    }

    // XÓA BỎ CÁC HÀM VÒNG ĐỜI KHÔNG CẦN THIẾT
}

@Composable
private fun AppNavigation() {
    // Khởi tạo MainViewModel, nó sẽ tồn tại suốt vòng đời của app
    val mainViewModel: MainViewModel = hiltViewModel()
    val lifecycleOwner = LocalLifecycleOwner.current

    // DisposableEffect bây giờ sẽ an toàn vì nó gọi các hàm trong ViewModel
    // đã được Hilt khởi tạo đúng cách.
    DisposableEffect(lifecycleOwner, mainViewModel) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_RESUME -> mainViewModel.registerReceiver()
                Lifecycle.Event.ON_PAUSE -> mainViewModel.unregisterReceiver()
                else -> {} // Không làm gì ở các event khác
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)

        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
        }
    }

    val navController = rememberNavController()
    NavHost(navController = navController, startDestination = "discovery") {
        // Màn hình Discovery
        composable("discovery") {
            DiscoveryRoute(
                viewModel = hiltViewModel(),
                onOpenChat = { peerAddress ->
                    navController.navigate("chat/$peerAddress")
                }
            )
        }

        // Màn hình Chat
        composable(
            route = "chat/{peerAddress}",
            arguments = listOf(navArgument("peerAddress") { type = NavType.StringType })
        ) {
            ChatRoute(
                viewModel = hiltViewModel(),
                onBack = { navController.popBackStack()},
                peerAddress = it.arguments?.getString("peerAddress")!!
            )
        }
    }
}

package com.bsit.p2p_chat

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.runtime.Composable
import androidx.compose.runtime.DisposableEffect
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.platform.LocalLifecycleOwner
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.bsit.p2p_chat.ui.chat.ChatRoute
import com.bsit.p2p_chat.ui.discovery.DiscoveryRoute
import com.bsit.p2p_chat.ui.theme.P2P_ChatTheme
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    // XÓA BỎ HOÀN TOÀN CÁC THUỘC TÍNH INJECT
    // @Inject lateinit var wifiDirectManager: WifiDirectManager
    // @Inject lateinit var socketTransport: SocketMessageTransport

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            P2P_ChatTheme {
                // Toàn bộ logic được chuyển vào AppNavigation
                AppNavigation()
            }
        }
    }

    // XÓA BỎ CÁC HÀM VÒNG ĐỜI KHÔNG CẦN THIẾT
}

@Composable
private fun AppNavigation() {
    val app = LocalContext.current.applicationContext as P2PChatApplication
    val container = app.container

    val mainViewModel: MainViewModel = viewModel(
        factory = MainViewModelFactory(container.wifiDirectManager, container.socketMessageTransport)
    )
    val lifecycleOwner = LocalLifecycleOwner.current

    // DisposableEffect bây giờ sẽ an toàn vì nó gọi các hàm trong ViewModel
    // đã được Hilt khởi tạo đúng cách.
    DisposableEffect(lifecycleOwner, mainViewModel) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_RESUME -> mainViewModel.registerReceiver()
                Lifecycle.Event.ON_PAUSE -> mainViewModel.unregisterReceiver()
                else -> {} // Không làm gì ở các event khác
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)

        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
        }
    }

    val navController = rememberNavController()
    NavHost(navController = navController, startDestination = "discovery") {
        // Màn hình Discovery
        composable("discovery") {
            val discoveryViewModel: DiscoveryViewModel = viewModel(
                factory = DiscoveryViewModelFactory(
                    container.peerDiscoveryDataSource,
                    container.wifiDirectManager,
                    container.socketMessageTransport
                )
            )
            DiscoveryRoute(
                viewModel = discoveryViewModel,
                onOpenChat = { peerAddress ->
                    navController.navigate("chat/$peerAddress")
                }
            )
        }

        // Màn hình Chat
        composable(
            route = "chat/{peerAddress}",
            arguments = listOf(navArgument("peerAddress") { type = NavType.StringType })
        ) {
            val chatViewModel: ChatViewModel = viewModel(
                viewModelStoreOwner = it,
                factory = ChatViewModelFactory(it, container.chatRepository, it.arguments)
            )
            ChatRoute(
                viewModel = chatViewModel,
                onBack = { navController.popBackStack() },
                peerAddress = it.arguments?.getString("peerAddress")!!
            )
        }
    }
}

