package com.bsit.p2p_chat.wifi_direct

import android.Manifest
import android.annotation.SuppressLint
import android.content.Context
import android.content.IntentFilter
import android.net.wifi.p2p.WifiP2pConfig
import android.net.wifi.p2p.WifiP2pDevice
import android.net.wifi.p2p.WifiP2pManager
import android.os.Looper
import android.util.Log
import android.content.Intent
import android.net.wifi.p2p.WifiP2pInfo
import android.os.Build
import android.provider.Settings
import androidx.annotation.RequiresPermission
import com.bsit.p2p_chat.socket.SocketMessageTransport
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class WifiDirectManager @Inject constructor(
    @ApplicationContext private val context: Context,
    private val manager: WifiP2pManager,
    private val channel : WifiP2pManager.Channel,
    private val socketTransport: SocketMessageTransport // Inject SocketMessageTransport
) {
//  Các StateFlow để theo dõi trạng thái Wi-Fi và trạng thái kết nối.
    private val peersFlow = MutableStateFlow<List<WifiP2pDevice>>(emptyList())
    private val wifiStateFlow = MutableStateFlow(false)
    private val _connectionInfo = MutableStateFlow<WifiP2pInfo?>(null)

    val connectionInfo: Flow<WifiP2pInfo?> = _connectionInfo.asStateFlow()
    fun observeWifiState(): Flow<Boolean> = wifiStateFlow.asStateFlow()
    fun observePeers(): Flow<List<WifiP2pDevice>> = peersFlow.asStateFlow()

    // Tạo IntentFilter để đăng ký các event của Wifi Direct
    private val intentFilter = IntentFilter().apply {
        addAction(WifiP2pManager.WIFI_P2P_STATE_CHANGED_ACTION)
        addAction(WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION)
        addAction(WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION)
        addAction(WifiP2pManager.WIFI_P2P_THIS_DEVICE_CHANGED_ACTION)
    }

    fun openWifiSettings() { //kiểm tra xem thiết bị của người dùng có đang chạy hệ điều hành Android 10 (API level 29) hoặc mới hơn hay không
        val intent = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            Intent(Settings.Panel.ACTION_WIFI)
        } else {
            Intent(Settings.ACTION_WIFI_SETTINGS)
        }
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        context.startActivity(intent)
    }

    // Tích hợp WiFiDirectBroadcastReceiver
    @SuppressLint("MissingPermission")
    val receiver = WiFiDirectBroadcastReceiver(
        onP2pStateChanged = { // Bắt sự kiện Wi-Fi bật/tắt
            isEnabled ->
            wifiStateFlow.value = isEnabled
        },
        onPeersChanged = { // Khi hệ thống phát hiện có thiết bị xung quanh, yêu cầu lấy danh sách (requestPeers)
            manager.requestPeers(channel) { peers ->
                peersFlow.value = peers.deviceList.toList()
                onPeersUpdated(peersFlow.value)
            }
        },
        onConnectionChanged = { // Xử lý thay đổi kết nối
            manager.requestConnectionInfo(channel) { info ->
                _connectionInfo.value = info
            }
        },
        onThisDeviceChanged = { // Xử lý thay đổi thiết bị của bạn

        }
    )

    // Ra lệnh xử lý tìm kiếm thiết bị ở phần cứng
    @RequiresPermission(allOf = [Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.NEARBY_WIFI_DEVICES])
    @SuppressLint("MissingPermission") // Cần đảm bảo đã xin quyền lúc runtime

    fun discoverPeers() {
        manager.discoverPeers(channel , object : WifiP2pManager.ActionListener{
            override fun onSuccess() {
                Log.d("WifiDirectManager", "Peer discovery started successfully.")
            }

            override fun onFailure(reason: Int) {
                Log.e("WifiDirectManager", "Peer discovery failed with reason code: $reason")
            }
        })
    }
    fun onPeersUpdated(devices: List<WifiP2pDevice>) {
        peersFlow.value = devices
    }

    @SuppressLint("MissingPermission")
    fun connectToPeer( device: WifiP2pDevice) {
        val config = WifiP2pConfig().apply {
            deviceAddress = device.deviceAddress
        }
        manager.connect(channel, config, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Log.d("WifiDirectManager", "Connection initiated successfully.")
            }

            override fun onFailure(reason: Int) {
                Log.e("WifiDirectManager", "Connection initiation failed with reason code: $reason")
            }
        })
    }

    // Các hàm để đăng ký và hủy đăng ký Receiver (Gọi trên UI Layer)
    fun registerReceiver() {
        context.registerReceiver(receiver, intentFilter)
    }

    fun unregisterReceiver() {
        context.unregisterReceiver(receiver)
    }
}

